void dei_out_defroster_pulsed_on( void *payload)
{
	
	DEI_OUT_DEFROSTER_PULSED_RESET();
		
	DEI_OUT_DEFROSTER_PULSED( 2 ,80 ,1 , 1 );		

}

//--------------------------------------------------------------------------//

void dei_out_defroster_pulsed_off( void *payload)
{
	
	DEI_OUT_DEFROSTER_PULSED_RESET();
		
	DEI_OUT_DEFROSTER_PULSED( 2 ,80 ,1 , 1 );		

}

